  for (const x of tab) {
    if (x > tails[tails.length - 1]) {
      // Ajouter si plus grand que le dernier élément actuel dans tails
      tails.push(x);
    } else {
      let low = 0, high = tails.length - 1;
      while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (tails[mid] < x) low = mid + 1; // Recherche de la première position >= x
