function trier_tableau(arr) {
  if (arr.length <= 1) return [...arr]; // Copie pour ne pas altérer l'original
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    // Trouver le minimum dans la sous-partie [i...end]
    let minIndex = i;
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[j] < arr[minIndex]) minIndex = j;
